const { customer, createdAfter, createdBefore, limit, startingAfter } = $.input;

const params = {};
if (customer) params.customer = customer;
if (createdAfter) params['created[gte]'] = String(createdAfter);
if (createdBefore) params['created[lte]'] = String(createdBefore);
if (limit) params.limit = String(Math.max(1, Math.min(100, limit)));
if (startingAfter) params.starting_after = startingAfter;

return { params };

const resp = $.steps.listPaymentIntents.response || {};
const intents = resp.data || [];

const keysToRemove = [
  'object', 'amount_details', 'application', 'application_fee_amount',
  'canceled_at', 'cancellation_reason', 'client_secret', 'confirmation_method',
  'invoice', 'last_payment_error', 'latest_charge', 'livemode', 'next_action',
  'on_behalf_of', 'payment_method_options', 'processing', 'receipt_email',
  'review', 'setup_future_usage', 'shipping', 'source', 'statement_descriptor',
  'statement_descriptor_suffix', 'transfer_data', 'transfer_group'
];

const compressed = intents.map(intent => {
  const c = { ...intent };
  keysToRemove.forEach(k => delete c[k]);
  return c;
});

return {
  paymentIntents: compressed,
  totalReturned: compressed.length,
  hasMore: resp.has_more || false,
  summary: `Retrieved ${compressed.length} payment intent${compressed.length === 1 ? '' : 's'}`
};
